-- drizzle-kit runner ledger, as production holds it (read-only, 2026-10-23).
-- The runner creates this table itself; no migration file does. Hashes are the
-- sha256 of drizzle/migrations/*.sql; created_at values are production's.
CREATE SCHEMA IF NOT EXISTS drizzle;
CREATE TABLE IF NOT EXISTS drizzle.__drizzle_migrations (
  id SERIAL PRIMARY KEY,
  hash text NOT NULL,
  created_at bigint
);
SELECT setval('drizzle.__drizzle_migrations_id_seq', 23);
